package br.com.sussmartcare.prehospital.adapters.in.rest; import br.com.sussmartcare.prehospital.application.*; import br.com.sussmartcare.prehospital.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/pre-hospital") public class PreHospitalController{private final PreHospitalApplicationService app;public PreHospitalController(PreHospitalApplicationService a){app=a;}public record CreateRequest(@NotNull UUID patientId,UUID visitId,@NotBlank String ambulanceId,@NotNull UUID destinationFacilityId,Instant estimatedArrivalAt){}public record EtaRequest(@NotNull Instant estimatedArrivalAt){}public record RiskRequest(@NotBlank String riskLevel){}@PostMapping("/encounters")public ResponseEntity<PreHospitalEncounter> create(@Valid @RequestBody CreateRequest r){return ResponseEntity.status(201).body(app.create(r.patientId(),r.visitId(),r.ambulanceId(),r.destinationFacilityId(),r.estimatedArrivalAt()));}@GetMapping("/encounters/{id}")public PreHospitalEncounter get(@PathVariable UUID id){return app.get(id);}@PutMapping("/encounters/{id}/eta")public PreHospitalEncounter eta(@PathVariable UUID id,@Valid @RequestBody EtaRequest r){return app.eta(id,r.estimatedArrivalAt());}@PutMapping("/encounters/{id}/risk")public PreHospitalEncounter risk(@PathVariable UUID id,@Valid @RequestBody RiskRequest r){return app.risk(id,r.riskLevel());}}
